/**
 * Time zone -> coarse place. This is the only source of position in One Sky:
 * a visitor is put at the reference city of their browser's IANA time zone
 * (or a city they pick with searchPlaces), never at a measured location.
 *
 * Data: src/lib/tzdata.ts, generated by scripts/gen-tz.py from IANA tzdata.
 */
import { ALIASES, COUNTRIES, RAW_PLACES } from './tzdata';
import { isValidTimeZone, utcOffsetMinutes } from './time';

export interface Place {
  /** Place key for cities beyond the time-zone table ("g" + GeoNames id). Absent for zone places, whose key is `tz`. */
  key?: string;
  /** State or province code, where city names repeat a lot (US, Canada, Australia). */
  region?: string;
  tz: string;
  lat: number;
  lon: number;
  city: string;
  country: string;
  cc: string;
}

/** Must stay in step with default_city() in scripts/gen-tz.py. */
function defaultCity(tz: string): string {
  return tz.slice(tz.lastIndexOf('/') + 1).replace(/_/g, ' ');
}

/** One Place per IANA zone that has coordinates, sorted by zone name. */
export const PLACES: Place[] = RAW_PLACES.map(([tz, lat, lon, city, cc]) => ({
  tz,
  lat,
  lon,
  city: city || defaultCity(tz),
  country: COUNTRIES[cc] ?? cc,
  cc,
}));

const byTz = new Map<string, Place>();
for (const p of PLACES) {
  byTz.set(p.tz, p);
  byTz.set(p.tz.toLowerCase(), p);
}
const aliasLower = new Map<string, string>();
for (const k of Object.keys(ALIASES)) aliasLower.set(k.toLowerCase(), ALIASES[k]);

/** Last-resort place if everything else fails (it cannot, but nothing here may throw). */
const HOME: Place = byTz.get('Europe/London') ??
  PLACES[0] ?? { tz: 'Europe/London', lat: 51.51, lon: -0.13, city: 'London', country: 'United Kingdom', cc: 'GB' };

/**
 * The Place for an IANA zone name. Never throws.
 *
 *  1. exact zone name (case-insensitive);
 *  2. old or link name via the tzdata `backward` aliases
 *     (Asia/Calcutta -> Kolkata, US/Pacific -> Los Angeles);
 *  3. otherwise (UTC, Etc/GMT+5, a zone newer than our table, garbage,
 *     undefined) fall back on the UTC offset: the zone's own current offset if
 *     Intl can resolve it, else this device's local offset. See placeForOffset.
 *
 * `date` only matters for step 3 and exists so the fallback can be tested.
 */
export function placeForTimeZone(tz: string | undefined, date: Date = new Date()): Place {
  try {
    const name = typeof tz === 'string' ? tz.trim() : '';
    if (name) {
      const lower = name.toLowerCase();
      const hit = byTz.get(name) ?? byTz.get(lower);
      if (hit) return hit;
      const alias = ALIASES[name] ?? aliasLower.get(lower);
      const viaAlias = alias ? byTz.get(alias) : undefined;
      if (viaAlias) return viaAlias;
    }
    const when = Number.isFinite(date.getTime()) ? date : new Date();
    const offset = name && isValidTimeZone(name)
      ? utcOffsetMinutes(name, when)
      : -when.getTimezoneOffset();
    return placeForOffset(offset, when);
  } catch {
    return HOME;
  }
}

/** Exact lookup by canonical zone name only: no aliases, no fallback. For validating remote data. */
export function placeByTz(tz: unknown): Place | undefined {
  return typeof tz === 'string' ? byTz.get(tz) : undefined;
}

const offsetCache = new Map<string, Place>();

/**
 * Deterministic fallback: a UTC offset (minutes east) -> a Place.
 *
 * The offset's natural meridian is offset/4 degrees (UTC+1 -> 15 E). Among the
 * places whose zone has exactly that offset at `date`, pick the one whose
 * longitude is closest to the meridian (ties: nearer the equator, then zone
 * name). Research stations in Antarctica are only used if nothing else
 * matches. If no zone has the offset at all, the same rule runs over every
 * place, so the answer is still on the nearest meridian.
 */
export function placeForOffset(offsetMinutes: number, date: Date = new Date()): Place {
  const offset = Number.isFinite(offsetMinutes) ? Math.round(offsetMinutes) : 0;
  const ms = Number.isFinite(date.getTime()) ? date.getTime() : Date.now();
  // Zone offsets only ever change on quarter-hour boundaries.
  const key = `${offset}|${Math.floor(ms / 900000)}`;
  const cachedPlace = offsetCache.get(key);
  if (cachedPlace) return cachedPlace;

  const when = new Date(ms);
  const meridian = wrap180(offset / 4);
  const matching = PLACES.filter(
    (p) => isValidTimeZone(p.tz) && utcOffsetMinutes(p.tz, when) === offset,
  );
  const inhabited = matching.filter((p) => p.cc !== 'AQ');
  const pool = inhabited.length ? inhabited : matching.length ? matching : PLACES;

  let best = HOME;
  let bestScore = Infinity;
  let bestLat = Infinity;
  for (const p of pool) {
    const score = Math.abs(wrap180(p.lon - meridian));
    const absLat = Math.abs(p.lat);
    if (
      score < bestScore ||
      (score === bestScore && (absLat < bestLat || (absLat === bestLat && p.tz < best.tz)))
    ) {
      best = p;
      bestScore = score;
      bestLat = absLat;
    }
  }

  if (offsetCache.size > 200) offsetCache.clear();
  offsetCache.set(key, best);
  return best;
}

/** Lowercase, strip diacritics and punctuation: "São Tomé" -> "sao tome", "St. John's" -> "st johns". */
function fold(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[ʻ'’.]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

interface Indexed {
  place: Place;
  city: string;
  country: string;
  /** zone's own last segment, so "Tahiti" still finds Papeete */
  zone: string;
}

let searchIndex: Indexed[] | null = null;

function index(): Indexed[] {
  if (!searchIndex) {
    searchIndex = PLACES.map((place) => ({
      place,
      city: fold(place.city),
      country: fold(place.country),
      zone: fold(defaultCity(place.tz)),
    })).sort((a, b) => (a.city < b.city ? -1 : a.city > b.city ? 1 : a.place.tz < b.place.tz ? -1 : 1));
  }
  return searchIndex;
}

/**
 * Find places by city or country, ignoring case and diacritics.
 * Ranked: city starts with the query; a later word of the city starts with it;
 * country starts with it; then substring matches (city, zone name, country).
 * Alphabetical by city within a rank. An empty query returns [].
 */
export function searchPlaces(q: string, limit = 8): Place[] {
  const query = typeof q === 'string' ? fold(q) : '';
  const max = Number.isFinite(limit) ? Math.floor(limit) : 8;
  if (!query || max <= 0) return [];

  const ranks: Place[][] = [[], [], [], [], [], []];
  for (const e of index()) {
    let rank = -1;
    if (e.city.startsWith(query)) rank = 0;
    else if (e.city.includes(' ' + query) || e.zone.startsWith(query)) rank = 1;
    else if (e.country.startsWith(query) || e.country.includes(' ' + query)) rank = 2;
    else if (e.city.includes(query)) rank = 3;
    else if (e.zone.includes(query)) rank = 4;
    else if (e.country.includes(query)) rank = 5;
    if (rank >= 0) ranks[rank].push(e.place);
  }
  return ranks.flat().slice(0, max);
}

/** FNV-1a, 32 bit. */
function hash32(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** mulberry32 step: a well-mixed float in [0, 1) from a 32-bit state. */
function mix(state: number): number {
  let t = (state + 0x6d2b79f5) | 0;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

export const JITTER_DEGREES = 0.6;

/**
 * A small deterministic offset from a place, so several people in one zone do
 * not stack on a single point: up to ±0.6° in latitude and in longitude, fixed
 * by `seed` (and the zone). Same seed, same spot. Rounded to 3 decimals.
 */
export function jitter(place: Place, seed: string): { lat: number; lon: number } {
  const h = hash32(`${seed}|${place.tz}`);
  const dLat = (mix(h) * 2 - 1) * JITTER_DEGREES;
  const dLon = (mix(h ^ 0x9e3779b9) * 2 - 1) * JITTER_DEGREES;
  const lat = Math.max(-89.5, Math.min(89.5, place.lat + dLat));
  const lon = wrap180(place.lon + dLon);
  return { lat: round3(lat), lon: round3(lon) };
}

function round3(x: number): number {
  const r = Math.round(x * 1000) / 1000;
  return r === 0 ? 0 : r;
}

function wrap180(deg: number): number {
  return ((((deg + 180) % 360) + 360) % 360) - 180;
}
